/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    AttackSpeedPreviewInput, getOutOfRoundAttackSpeedPreview, LifestealPreviewInput, getOutOfRoundLifestealPreview, FreeUpgradeChancePreviewInput, getOutOfRoundFreeUpgradeChancePreview
 * depends    src/mechanics/constants
 * used by    src/mechanics/calculators/specs-generated, src/mechanics/index
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */
import {
  ATTACK_SPEED_LEVEL_SCALE,
  ATTACK_SPEED_OFFSET,
  FREE_UPGRADE_LEVEL_SCALE,
  LIFESTEAL_TIER_POW,
  LIFESTEAL_TIER_SCALE,
} from './constants'

export interface AttackSpeedPreviewInput {
  workshopLevel: number
  workshopCurveMult: number
  catalogMult: number
  moduleMult: number
  relicAttackSpeedMult?: number
  labMult?: number
  storedMult?: number
  cardMult?: number
}

export function getOutOfRoundAttackSpeedPreview(input: AttackSpeedPreviewInput): number {
  const L = Math.max(0, input.workshopLevel)
  let core = (L * ATTACK_SPEED_LEVEL_SCALE + ATTACK_SPEED_OFFSET) * input.catalogMult * input.moduleMult
  if (input.relicAttackSpeedMult != null) core *= input.relicAttackSpeedMult
  let raw = core + input.workshopCurveMult
  raw *= (input.labMult ?? 0) + 1
  raw *= (input.storedMult ?? 0) + 1
  if (input.cardMult != null) raw *= input.cardMult
  return raw
}

export interface LifestealPreviewInput {
  catalogTier: number
  workshopCurveValue: number
}

export function getOutOfRoundLifestealPreview(input: LifestealPreviewInput): number {
  const tierPow = Math.pow(Math.max(0, input.catalogTier), LIFESTEAL_TIER_POW)
  return input.workshopCurveValue + input.catalogTier * LIFESTEAL_TIER_SCALE * tierPow
}

export interface FreeUpgradeChancePreviewInput {
  workshopCurveValue: number
  levelField: number
  enhancementRowAdd?: number
  labMult?: number
  cardMultA?: number
  cardMultB?: number
}

/** Shared tail for free attack/defense/utility upgrade chance getters. */
export function getOutOfRoundFreeUpgradeChancePreview(input: FreeUpgradeChancePreviewInput): number {
  let core = input.workshopCurveValue + input.levelField * FREE_UPGRADE_LEVEL_SCALE
  if (input.enhancementRowAdd != null) core += input.enhancementRowAdd
  core = (core + (input.labMult ?? 0)) + 1
  if (input.cardMultA != null) core *= input.cardMultA
  if (input.cardMultB != null) core *= input.cardMultB
  return core
}
